# פרק 3 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=3
TITLE='חקיקה ראשית וחקיקת משנה'
SUM=[' <p>שני סוגי נורמות חקוקות, הנבדלים ב<strong>מקור הסמכות</strong> וב<strong>מעמד</strong>.</p> <h3>3.1 חקיקה ראשית</h3> <p>חוקים שמחוקקת ה<strong>כנסת</strong> — הרשות המחוקקת. זהו המקור הנורמטיבי המרכזי (מתחת לחוקי היסוד), המתקבל בהליך חקיקה של שלוש קריאות.</p> <h3>3.2 חקיקת משנה</h3> <p><strong>תקנות, צווים וכללים</strong> שמתקינה ה<strong>רשות המבצעת</strong> (שר, רשות) — אך ורק מכוח <strong>הסמכה מפורשת בחוק ראשי</strong>. תכליתה: השלמת פרטים טכניים-יישומיים שאין זה יעיל לקבוע בחוק עצמו.</p> <h3>3.3 היחס ביניהן</h3> <p>חקיקת משנה <strong>כפופה</strong> לחקיקה הראשית; תקנה הסותרת את חוק ההסמכה או חורגת ממנו — בטלה. עניינים עקרוניים ("<strong>הסדרים ראשוניים</strong>") צריכים להיקבע בחקיקה ראשית.</p> <h3>3.4 נקודות מפתח למבחן</h3> <ul><li>ראשית — הכנסת; משנה — הרשות המבצעת מכוח הסמכה.</li><li>חקיקת משנה כפופה לחוק המסמיך; חריגה בטלה.</li><li>הסדרים ראשוניים — בחקיקה ראשית.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('בג״ץ 1/49 בז׳רנו נ׳ שר המשטרה', 'העותרים עסקו שנים רבות בכתיבת בקשות ובטיפול בהליכי רישוי רכב עבור לקוחות. משרדי התנועה בתל אביב אסרו עליהם להיכנס ולעסוק בכך, בטענה שעבודתם אינה נחוצה.', 'העתירה התקבלה. נקבע שהרשות אינה מוסמכת למנוע מאדם לעסוק במשלח ידו כשאין חוק המסמיך אותה לכך. זה פסק הדין הראשון שבו הוכר חופש העיסוק כזכות יסוד והראשון שבו נפסלה פעולה של רשות בשל היעדר סמכות — אבן היסוד לעקרון החוקיות ולמגבלות על חקיקת משנה.'), ('ע״א 311/57 היועץ המשפטי לממשלה נ׳ מ. דיזנגוף ושות׳ (שיט) בע״מ', 'דיון בתוקפה של חקיקת משנה ובאמת המידה שלפיה בית המשפט רשאי לפסול תקנות בשל חוסר סבירות.', 'השופט ברנזון קבע שאם חקיקת משנה ״כה בלתי הגיונית ובלתי נסבלת״ עד שאדם בר דעת לא יעלה על דעתו ששר סביר היה מתקין אותה, יש להסיק שהמחוקק לא התכוון להעניק כוח כזה. חוסר סבירות קיצוני הוא אפוא עילה לפסילת תקנה, והוא מעוגן ברעיון של חריגה מן ההסמכה.'), ('בג״ץ 337/81 מיטרני נ׳ שר התחבורה', 'דיון בתוקפן של תקנות שהותקנו מכוח חוק בתחום התחבורה, ובשאלת היקף ההסמכה שהעניק המחוקק לרשות המבצעת.', 'בית המשפט קבע שההסדרים הראשוניים נתונים למחוקק, ואילו הרשות המבצעת מוסמכת להסדרים משניים בלבד. פסק הדין הוא אחד המקורות המרכזיים שעליהם נשענה דוקטרינת ההסדרים הראשוניים, כפי שצוטט בהרחבה בבג״ץ רובינשטיין.'), ('בג״ץ 3267/97 רובינשטיין נ׳ שר הביטחון', 'עתירות נגד הסדר דחיית השירות של תלמידי ישיבות, שהתבסס על סמכותו הכללית של שר הביטחון לפי ס׳ 36 לחוק שירות ביטחון לדחות שירות מ״טעמים אחרים״.', 'הרכב של 11 שופטים קבע שלפי עקרונות שלטון החוק והפרדת הרשויות, הכנסת חייבת לקבוע את ההסדרים הראשוניים — המדיניות הכללית ואמות המידה. בשל היקף הדחיות והמחלוקת הציבורית, ההסדר הוא הכרעה עקרונית שמחייבת חקיקה ראשית, והסמכות הכללית לפי ס׳ 36 אינה מכסה אותה. ההכרזה על הבטלות הושעתה ל־12 חודשים כדי לאפשר חקיקה.'), ('בג״ץ 6971/98 פריצקי נ׳ ממשלת ישראל', 'שביתה במשרד הפנים מנעה מאזרחים רבים לעדכן פרטים, והממשלה התקינה תקנות שעת חירום על אמצעי זיהוי בבחירות לרשויות המקומיות, ימים ספורים לפני הבחירות.', 'העתירה נדחתה ברוב דעות, משום שביטול התקנות סמוך כל כך לבחירות היה פוגע בזכות ההצבעה. עם זאת נקבע שהתקנת תקנות שעת חירום פוגעת בהפרדת הרשויות ובשלטון החוק, ולכן יש להשתמש בכלי במשורה ובמידתיות. השופט מ׳ חשין, בדעת מיעוט, סבר שמאחר שאפשר היה לפנות לכנסת, לא הייתה הצדקה לתקנות חירום.'), ('בג״ץ 2109/20 בן מאיר נ׳ ראש הממשלה', 'במרץ 2020 הותקנו תקנות שעת חירום והתקבלה החלטת ממשלה שהסמיכו את השב״כ לאתר טלפונים של חולי קורונה ומגעיהם, ללא צו שיפוטי.', 'בדיון הראשוני עלו שאלות יסוד: האם מצב חירום לפי ס׳ 38 כולל חירום שאינו ביטחוני, והאם ס׳ 39(ד) מטיל מגבלה מוחלטת על פגיעה בכבוד האדם. בית המשפט התיר את האיכון רק בכפוף לפיקוח של ועדת כנסת, ובהמשך קבע שהמשך השימוש באמצעי כזה מחייב הסדרה בחקיקה ראשית — יישום עכשווי של ההסדרים הראשוניים ושל הזהירות בתקנות חירום.'), ('בג״ץ 6198/23 התנועה למען איכות השלטון בישראל נ׳ שר הביטחון', 'לאחר שפג תוקפו של ההסדר החוקי האחרון לדחיית שירות תלמידי ישיבות, נמשכה בפועל אי־אכיפה (על סמך החלטת ממשלה שהורתה שלא לאכוף את החוק) ונמשך מימון הישיבות.', 'בית המשפט, בהרכב מורחב של תשעה שופטים ופה אחד, קבע שאין כיום מקור חוקי להימנע מגיוס תלמידי ישיבות, שעל המדינה לאכוף את חוק שירות הביטחון, שאין סמכות להמשיך להעביר כספי תמיכה לישיבות עבור תלמידים אלה, ושההוראה בהחלטת הממשלה שלא לאכוף את החוק התקבלה בחוסר סמכות. נקבע במפורש, בהמשך להלכת רובינשטיין, שהסוגיה מחייבת הסדר ראשוני בחקיקה ראשית.')]
QS=[{'q': 'לפי חוק הפרשנות, מהי ״תקנה״?', 'o': ['כל מסמך שפרסם משרד ממשלתי', 'הוראה שניתנה מכוח חוק והיא בת־פעל תחיקתי', 'כל החלטה של הממשלה', 'חוק של הכנסת שעניינו טכני'], 'c': 1, 'e': 'נכון. שני המבחנים: מכוח חוק, ובת־פעל תחיקתי — כלומר נורמה כללית.'}, {'q': 'שר פרסם מסמך שכותרתו ״צו״, הקובע כלל מחייב לכל בעלי המסעדות בארץ, מכוח סמכות בחוק. כיצד יסווג?', 'o': ['כתקנה — נורמה כללית מכוח חוק, בלי קשר לשם', 'כהנחיה פנימית שאינה מחייבת', 'כהוראת מינהל, כי הוא נקרא ״צו״', 'כחקיקה ראשית'], 'c': 0, 'e': 'נכון. ההגדרה בחוק הפרשנות מהותית: נורמה כללית שניתנה מכוח חוק היא ״תקנה״.'}, {'q': 'מה מעמדה של פקודה מנדטורית שעדיין בתוקף?', 'o': ['חקיקה ראשית — לפי חוק הפרשנות ״חוק״ הוא חוק של הכנסת או פקודה', 'חוק יסוד', 'הנחיה מינהלית בלבד', 'חקיקת משנה, כי לא חוקקה בכנסת'], 'c': 0, 'e': 'נכון. ההגדרה בחוק הפרשנות משווה את מעמד הפקודה למעמד חוק של הכנסת.'}, {'q': 'מתי נכנס לתוקף חיקוק, ככלל?', 'o': ['כשהוא מתפרסם בעיתונות', 'ביום ההצבעה בכנסת', 'ביום פרסומו ברשומות, בשעה 00.01, אלא אם נקבע בו מועד אחר', 'שלושים יום אחרי חתימת השר'], 'c': 2, 'e': 'נכון. ס׳ 10 לפקודת סדרי השלטון והמשפט (החל גם על תקנות) וס׳ 21 לחוק הפרשנות.'}, {'q': 'מה מסמיך ס׳ 37(א) לחוק־יסוד: הממשלה?', 'o': ['את הממשלה לשנות כל חוק', 'את בית המשפט להתקין תקנות', 'את הכנסת להאציל סמכות חקיקה לרשויות מקומיות', 'את השר הממונה על ביצועו של חוק להתקין תקנות לביצועו'], 'c': 3, 'e': 'נכון. אלה ״תקנות ביצוע״ — שנועדו להוציא את החוק לפועל ולא להוסיף לו הסדרים חדשים.'}, {'q': 'שר מתקין תקנה שקובעת עונש של שנת מאסר על הפרתה. התקנה אושרה בוועדת הכנסת. מה הדין?', 'o': ['תקפה, כי אושרה בוועדה', 'ההוראה תקפה רק אם פורסמה בעיתונות', 'ההוראה פגומה — ס׳ 2(א) לחוק העונשין מגביל מאסר שנקבע בתקנה לשישה חודשים, ואישור הוועדה אינו מרפא זאת', 'תקפה, כי ס׳ 2 לחוק העונשין מתיר כל עונש בתקנה'], 'c': 2, 'e': 'נכון. העונש חורג מהתקרה שבחוק העונשין, ולכן מדובר בחריגה מסמכות.'}, {'q': 'שר התקין תקנות שקובעות עבירה וקנס, ולא הביא אותן לאישור ועדת הכנסת. מה הבעיה?', 'o': ['התקנות תקפות אם השר התייעץ עם היועץ המשפטי', 'הבעיה היחידה היא שקנס אסור בתקנות', 'לפי ס׳ 2(ב) לחוק העונשין, תקנות שבהן נקבעו עבירות ועונשים (למעט חוקי עזר) טעונות אישור ועדה של הכנסת — פגם דיוני', 'אין בעיה — אישור ועדה נדרש רק בחוקי עזר'], 'c': 2, 'e': 'נכון. זו דרישה דיונית מפורשת, והיעדר אישור הוא עילה לבטלות.'}, {'q': 'מה קובע ס׳ 15 לחוק הפרשנות?', 'o': ['שרק הכנסת רשאית לבטל תקנות', 'שתקנות גוברות על חוקים', 'שהסמכה להתקין תקנות כוללת גם סמכות לתקנן, לשנותן, להתלותן או לבטלן בדרך שהותקנו', 'שתקנות פוקעות אחרי שנה'], 'c': 2, 'e': 'נכון. זה כלל עזר פרשני לגבי היקף ההסמכה.'}, {'q': 'חוק שמכוחו הותקנו תקנות בוטל, והחוק המבטל לא קבע הוראות חלופיות. מה דין התקנות?', 'o': ['הן ממשיכות לעמוד בתוקפן', 'הן הופכות לחקיקה ראשית', 'הן תקפות עוד שלושה חודשים', 'הן בטלות עם החוק — לפי ס׳ 23 לחוק הפרשנות'], 'c': 3, 'e': 'נכון. ״משבוטל חיקוק, בטלים עמו התקנות והמינויים שנעשו מכוחו״.'}, {'q': 'מה המשמעות של ultra vires בהקשר של חקיקת משנה?', 'o': ['תקנה שחורגת מהסמכות שהעניק החוק, ולכן בטלה', 'תקנה שנחקקה לפני קום המדינה', 'תקנה שפורסמה באיחור', 'תקנה שאושרה בכנסת'], 'c': 0, 'e': 'נכון. ״מעבר לכוח״ — פעולה מחוץ למסגרת ההסמכה.'}, {'q': 'חוק מסמיך שר ״לקבוע אגרות בעד רישיון דייג״. השר קובע בתקנות גם שרק מי שגר בטווח 10 ק״מ מהים יקבל רישיון. מה הדין?', 'o': ['התקנה בטלה כולה, כולל האגרות', 'הוראת הגבלת המגורים חורגת מההסמכה (שעניינה אגרות בלבד) ופוגעת בחופש העיסוק בלי הסמכה מפורשת — ultra vires', 'התקנה כולה תקפה', 'התקנה תקפה אם השר שוכנע שהיא חיונית'], 'c': 1, 'e': 'נכון. יש כאן חריגה מהותית מההסמכה ופגיעה בזכות יסוד בלי הסמכה מפורשת, כנדרש בס׳ 4 לחוק־יסוד: חופש העיסוק.'}, {'q': 'לפי חוקי היסוד בדבר זכויות האדם, באיזה תנאי מותר לפגוע בזכות מוגנת בתקנה?', 'o': ['רק בתקנה שאושרה בוועדת הכנסת', 'בכל תקנה שהתקין שר', 'אסור לפגוע בזכויות בשום תקנה', 'רק ״לפי חוק כאמור מכוח הסמכה מפורשת בו״, ובכפוף לתכלית ראויה ולמידתיות'], 'c': 3, 'e': 'נכון. זו לשון ס׳ 8 לחוק־יסוד: כבוד האדם וחירותו (וס׳ 4 לחוק־יסוד: חופש העיסוק).'}, {'q': 'מהי דוקטרינת ״ההסדרים הראשוניים״?', 'o': ['תקנות קודמות לחוקים בסדר הפרסום', 'ההכרעות העקרוניות — מדיניות כללית ואמות מידה — צריכות להיקבע בחקיקה ראשית, והרשות המבצעת קובעת הסדרים משניים בלבד', 'הכנסת רשאית להעביר כל הכרעה לשר בהסמכה כללית', 'חוק יסוד גובר על חוק רגיל'], 'c': 1, 'e': 'נכון. הדוקטרינה נשענת על הפרדת רשויות, שלטון החוק והדמוקרטיה, ונוסחה בבג״ץ רובינשטיין.'}, {'q': 'מה הכריע בג״ץ רובינשטיין לגבי הסדר דחיית השירות של תלמידי ישיבות?', 'o': ['שההסדר הוא הסדר ראשוני שחייב חקיקה ראשית, וההכרזה על בטלותו הושעתה ל־12 חודשים', 'שעל הצבא לגייס מיד את כל התלמידים, בלי תקופת מעבר', 'שההסדר חוקי, כי ס׳ 36 מאפשר דחייה מ״טעמים אחרים״', 'שבג״ץ אינו מוסמך לדון בעניין'], 'c': 0, 'e': 'נכון. בית המשפט דרש הכרעה בכנסת ואפשר לה זמן לחוקק.'}, {'q': 'מה נקבע ב־2024 בבג״ץ 6198/23?', 'o': ['שאין כיום מקור חוקי לפטור גורף של תלמידי ישיבות, שעל המדינה לאכוף את חוק שירות הביטחון ושאין סמכות להמשיך לממן את הישיבות עבורם', 'שהעתירות אינן שפיטות', 'שהלכת רובינשטיין בוטלה', 'שהממשלה רשאית להמשיך בהסדר מכוח החלטת ממשלה'], 'c': 0, 'e': 'נכון. בית המשפט הסתמך על הלכת רובינשטיין: הסוגיה מחייבת הסדר ראשוני בחקיקה ראשית.'}, {'q': 'מה מבחן הסבירות שנקבע בע״א 311/57 לגבי חקיקת משנה?', 'o': ['סבירות אינה עילה לפסילת תקנות', 'רק תקנות כלכליות נבחנות בסבירות', 'תקנה ״כה בלתי הגיונית ובלתי נסבלת״ שאדם בר דעת לא היה מעלה על דעתו ששר סביר מתקין אותה — מלמדת שהמחוקק לא התכוון להעניק כוח כזה', 'כל תקנה שבית המשפט אינו מסכים איתה בטלה'], 'c': 2, 'e': 'נכון. זה מבחן של חוסר סבירות קיצוני, המעוגן ברעיון של חריגה מההסמכה.'}, {'q': 'מה התנאים העיקריים להתקנת תקנות שעת חירום לפי חוק־יסוד: הממשלה?', 'o': ['די בהחלטת שר כלשהו, בכל זמן', 'רק בזמן מלחמה שהוכרזה בכנסת, ולתקופה של שנה', 'הכרזה על מצב חירום; תכלית של הגנה על המדינה, ביטחון הציבור והאספקה והשירותים החיוניים; ותקנות כאלה פוקעות אחרי שלושה חודשים אלא אם הוארכו בחוק', 'אישור מראש של בית המשפט העליון'], 'c': 2, 'e': 'נכון. אלה דרישות ס׳ 38 וס׳ 39(א) ו־(ו).'}, {'q': 'מה אסור לתקנות שעת חירום לעשות, לפי ס׳ 39(ד) לחוק־יסוד: הממשלה?', 'o': ['להטיל מסים', 'לשנות חוק רגיל', 'להפקיע זמנית תוקף של חוק', 'למנוע פנייה לערכאות, לקבוע ענישה למפרע או להתיר פגיעה בכבוד האדם'], 'c': 3, 'e': 'נכון. אלה שלושת האיסורים המוחלטים שבס׳ 39(ד).'}, {'q': 'הממשלה מתקינה תקנות שעת חירום כדי להסדיר נושא כלכלי שגרתי, כשהכנסת מתכנסת ויכולה לחוקק בתוך ימים. מה עמדת הפסיקה?', 'o': ['התקנות תקפות אם השר הודיע עליהן לתקשורת', 'התקנות תקפות לשנה שלמה', 'אין מניעה — בכל מצב חירום מוכרז הממשלה חופשית לבחור בתקנות', 'אין מקום לתקנות שעת חירום כשניתן להסדיר את העניין בחקיקה רגילה, ויש להשתמש בכלי במשורה (פורז, פריצקי)'], 'c': 3, 'e': 'נכון. בבג״ץ פורז נקבע שאין מקום לתקנות חירום כשאפשר לחוקק, ובפריצקי הודגשה הפגיעה בהפרדת הרשויות.'}, {'q': 'עותר טוען שחוק של הכנסת בטל משום שהוא ״בלתי סביר באופן קיצוני״, כמו שנפסלות תקנות. מה התשובה העקרונית?', 'o': ['הטענה נכונה רק אם החוק לא אושר בוועדה', 'הטענה נכונה — חוק נבחן בדיוק כמו תקנה', 'הטענה שגויה — חוק של הכנסת אינו נבחן לפי עילות המשפט המינהלי כמו סבירות, ויכול להיפסל רק בשל סתירה לחוק יסוד', 'הטענה נכונה אם החוק חוקק לפני 1980'], 'c': 2, 'e': 'נכון. ביקורת על חקיקה ראשית היא ביקורת חוקתית בלבד (שיעור 9), ואילו על תקנה חלות עילות רחבות.'}]
